import {parse,analyze,sample,defaults,techniques,scenarios} from './engine.js';
const $=id=>document.getElementById(id),esc=v=>String(v??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),time=v=>new Date(v).toISOString().slice(11,19),date=v=>new Date(v).toISOString().slice(0,10),fmt=n=>n.toLocaleString();
let rules=structuredClone(defaults),state=null,selected=null,page=0,range={start:'',end:''},view='overview';
try{const saved=JSON.parse(localStorage.getItem('loglens-demo-v2')||localStorage.getItem('loglens-v1'));if(saved?.import?.events&&saved.findings){state=saved;rules=defaults.map(r=>({...r,...(state.rules||[]).find(x=>x.id===r.id)}));}}catch{}
function persist(){try{localStorage.setItem(state.synthetic?'loglens-demo-v2':'loglens-v1',JSON.stringify(state));$('retention').textContent='Saved only in this browser · Delete anytime';}catch{$('retention').textContent='Storage full: session only. Export before closing.';}}
function loadImport(imp,synthetic,label){state={import:imp,synthetic,label,findings:analyze(imp.events,rules),rules:structuredClone(rules),created:new Date().toISOString(),scenario:synthetic?imp.file.match(/^synthetic-(.+)\.jsonl$/)?.[1]||'mixed':null};if(!synthetic)localStorage.removeItem('loglens-demo-v2');page=0;clearFilters(false);selected=null;persist();viewTo('overview');render();}
for(const id of ['scenario','start-scenario'])$(id).innerHTML=scenarios.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');
if(state)render();
function chosen(){return state?.findings.find(f=>f.id===selected);}
function filtered(){if(!state)return[];const q=$('search').value.toLowerCase(),f=view==='events'?chosen():null;if(view==='overview')return state.import.events;return state.import.events.filter(e=>(!q||[e.raw_line,e.hostname,e.username,e.source_ip].some(v=>String(v||'').toLowerCase().includes(q)))&&(!$('host').value||e.hostname===$('host').value)&&(!$('outcome').value||e.outcome===$('outcome').value)&&(!$('eventtype').value||e.event_type===$('eventtype').value)&&(!range.start||e.timestamp_utc>=range.start)&&(!range.end||e.timestamp_utc<=range.end)&&(!f||f.events.includes(e.event_id)));}
function clearFilters(draw=true){selected=null;page=0;range={start:'',end:''};['search','host','outcome','eventtype'].forEach(id=>$(id).value='');if(draw)render();}
function render(){if(!state)return;const all=state.import.events,fail=all.filter(e=>e.outcome==='failure').length,sources=new Set(all.map(e=>e.source_ip).filter(Boolean)).size;
 $('rerun').hidden=$('reset-demo').hidden=!state.synthetic;if(state.synthetic)$('scenario').value=state.scenario||state.import.file.match(/^synthetic-(.+)\.jsonl$/)?.[1]||'mixed';$('navcount').textContent=state.findings.length;$('source-label').textContent=state.label;document.querySelector('.tag').textContent=state.synthetic?'SYNTHETIC SAMPLE DATA':'LOCAL LOG FILE';
 const labels=[['Parsed events',all.length,`${state.import.unsupported.length} unsupported · ${state.import.duplicates} duplicates`],['Successful events',all.length-fail,'Successful logins or HTTP responses'],['Failed events',fail,'Failed logins or HTTP errors'],['Distinct sources',sources,`${new Set(all.map(e=>e.hostname).filter(Boolean)).size} observed hosts`],['Findings',state.findings.length,`${state.findings.filter(f=>f.priority==='High').length} high priority · Review required`]];
 $('stats').innerHTML=labels.map(([l,n,s])=>`<div class="stat"><div class="stat-label">${l}<span>${l==='Findings'?'⚑':'◷'}</span></div><strong${l==='Failed events'?' style="color:#bf7854"':l==='Findings'?' style="color:#aa7130"':''}>${fmt(n)}</strong><small>${s}</small></div>`).join('');
 const host=$('host').value;$('host').innerHTML='<option value="">All hosts</option>'+[...new Set(all.map(e=>e.hostname).filter(Boolean))].map(h=>`<option>${esc(h)}</option>`).join('');$('host').value=host;
 renderTimeline();renderOverviewSummary();renderFindings();renderDetail();renderEvents();renderInvestigations();}
function renderTimeline(){const all=state.import.events,events=filtered(),start=+new Date(all[0]?.timestamp_utc||Date.now()),end=+new Date(all.at(-1)?.timestamp_utc||start+1),bins=Array.from({length:60},()=>({success:0,failure:0,selected:false}));const step=Math.max(1,(end-start+1)/60),f=null;for(const e of events){const idx=Math.min(59,Math.floor((+new Date(e.timestamp_utc)-start)/step));bins[idx][e.outcome]++;}if(f)for(let i=0;i<60;i++)bins[i].selected=start+(i+1)*step>=+new Date(f.start)&&start+i*step<=+new Date(f.end);const max=Math.max(1,...bins.map(b=>b.success+b.failure));$('timeline').innerHTML=`<div class="panel-head"><div><h2>Event activity</h2><p>${all.length?date(all[0].timestamp_utc):'No events'} · ${events.length} matching events · UTC${f?' · Selected finding highlighted':''}</p></div><div class="legend"><span>Success</span><span>Failure</span></div></div><div class="chart" role="img" aria-label="Event counts by time; green successes and orange failures">${bins.map(b=>`<div class="bar ${b.selected?'selected':''}" title="${b.success} successes, ${b.failure} failures"><i style="height:${b.failure/max*100}%"></i><em style="height:${b.success/max*100}%"></em></div>`).join('')}</div><div class="axis">${[0,.25,.5,.75,1].map(x=>`<span>${time(start+(end-start)*x)} UTC</span>`).join('')}</div>`;}
function renderFindings(){const f=state.findings;const category=$('category')?.value||'';$('findings-panel').innerHTML=`<div class="panel-head"><div><h2>Findings <span class="badge">${f.length}</span></h2><p>Patterns to investigate, grounded in your logs</p></div><select id="category" aria-label="Finding category"><option value="">All rules</option>${rules.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></div><div id="finding-list"></div><div class="panel-foot"><span>Rules v1.1 · Evidence-based comparisons</span></div>`;$('category').value=category;function list(){$('finding-list').innerHTML=f.filter(x=>!$('category').value||x.rule.id===$('category').value).map(x=>`<button class="finding ${x.id===selected?'selected':''}" data-finding="${x.id}"><span class="finding-top"><span class="badge ${x.priority}">${x.priority.toUpperCase()}</span><span class="badge">${esc(x.status)}</span></span><strong>${esc(x.name)}</strong><span class="finding-meta"><span class="mono">${esc(x.source_ip)} → ${esc(x.username)}</span><span>${time(x.start)}</span></span><small>${esc(x.hostname)} · ${x.count} supporting events · ${x.rule.technique}</small></button>`).join('')||'<div class="empty">No configured rules matched these events.<br>This does not establish that the system is secure.</div>';document.querySelectorAll('[data-finding]').forEach(b=>b.onclick=()=>{selected=b.dataset.finding;page=0;render();});}list();$('category').onchange=list;}
function explanations(f){if(f.source_ips){const units=f.rule.id==='scan'?'distinct missing paths':f.rule.id==='errors'?'server-error responses':f.rule.id==='sql'||f.rule.id==='traversal'?'matching request patterns':'HTTP requests';return{observation:`${f.count} supporting HTTP records on ${f.hostname} from ${f.source_ips.length} distinct source IPs, between ${time(f.start)} and ${time(f.end)} UTC.`,rule_match:`Peak matching window: ${f.peak} ${units}; threshold ${f.rule.threshold} in ${f.rule.minutes} minutes${f.rule.id==='ddos'?`, with at least ${f.rule.min_sources} distinct source IPs`:''}. Overlapping windows are merged.`,interpretation:f.technique.description,alternatives:'Authorized load tests, a traffic surge, monitoring, crawlers, or application faults can produce similar patterns.',missing:f.technique.missing+' Activity outside the imported period is unknown.',next_steps:'Inspect request paths and status codes, compare with normal traffic, verify source ownership, and review WAF, application, database, CPU, and latency metrics.'};}return{observation:`${f.count} supporting authentication events from ${f.source_ip} on ${f.hostname}, involving ${f.username}, between ${time(f.start)} and ${time(f.end)} UTC.`,rule_match:`At least ${f.rule.threshold} ${['spray','invalid'].includes(f.rule.id)?'distinct accounts with failures':'failures'} within ${f.rule.minutes} minutes${f.rule.id==='success'?', followed by a successful login':''}. Overlapping matches are merged; the combined interval can be longer than one rule window.`,interpretation:f.technique.description,alternatives:'An outdated client password, an authorized test, or an operator retrying credentials may explain this activity.',missing:`${f.technique.missing} Activity outside the imported period, session commands, and source ownership are unknown.`,next_steps:'Confirm whether this source is authorized. Review surrounding authentication events, account ownership, MFA records, and post-login session activity.'};}
function renderDetail(){const f=chosen();if(!f){$('detail').innerHTML='<p class="eyebrow">INVESTIGATION DETAIL</p><h3>Start with the evidence</h3><p>Select a finding to see exactly why it matched, the supporting events, and what to check next.</p><div class="technique"><h4>Technique comparison ≠ attribution</h4><p>Login patterns alone cannot identify a threat actor or prove account compromise.</p></div>';return;}const x=explanations(f);$('detail').innerHTML=`<div class="row"><p class="eyebrow" style="margin:0">FINDING DETAIL</p><button id="unselect" aria-label="Clear selected finding">×</button></div><h3>${esc(f.name)}</h3><div class="row"><span class="badge ${f.priority}">${f.priority} priority</span><select id="status" aria-label="Finding status">${['New','Investigating','Expected activity','Resolved'].map(s=>`<option${s===f.status?' selected':''}>${s}</option>`).join('')}</select></div><h4>What happened</h4><p>${esc(x.observation)}</p><h4>Why it was flagged</h4><p>${esc(x.rule_match)}</p><div class="technique"><span class="eyebrow">${f.technique.url?'MITRE ATT&CK COMPARISON':'OPERATIONAL CONTEXT'}</span><h4>${f.rule.technique} · ${esc(f.technique.name)}</h4><p>${esc(x.interpretation)}</p>${f.technique.url?`<a href="${f.technique.url}" target="_blank" rel="noopener noreferrer">View authoritative reference ↗</a>`:''}</div><details><summary>Alternative explanations & missing evidence</summary><p>${esc(x.alternatives)}</p><p>${esc(x.missing)}</p></details><details><summary>Next investigation steps</summary><p>${x.next_steps}</p></details><div class="evidence-actions"><button id="supporting">View supporting events →</button><button id="surrounding">Surrounding activity ↗</button></div><label for="group">Investigation group</label><input id="group" placeholder="e.g. SSH review — September" value="${esc(f.investigation||'')}" style="width:100%"><label for="note">Analyst notes · separate from evidence</label><textarea id="note" placeholder="Add context, checks, and conclusions…">${esc(f.notes)}</textarea><small id="savednote">Changes save on this device.</small>`;$('unselect').onclick=()=>{selected=null;render();};$('status').onchange=()=>{f.status=$('status').value;persist();renderFindings();renderInvestigations();};for(const [id,key] of [['note','notes'],['group','investigation']])$(id).oninput=()=>{f[key]=$(id).value;persist();$('savednote').textContent='Saved on this device';renderInvestigations();};$('supporting').onclick=()=>{clearFilters(false);selected=f.id;viewTo('events');render();};$('surrounding').onclick=()=>{clearFilters(false);$('host').value=f.hostname;$('search').value=f.source_ips?.length>1?'':f.source_ip;range={start:new Date(+new Date(f.start)-600000).toISOString(),end:new Date(+new Date(f.end)+600000).toISOString()};viewTo('events');render();};}
function renderEvents(){const events=filtered(),slice=events.slice(page*25,(page+1)*25);$('events-panel').innerHTML=`<div class="panel-head"><div><h2>Event evidence <span class="badge">${events.length}</span></h2><p>${chosen()?'Supporting records for the selected finding':'Original records with source locations'} · Click a record to view its raw line</p></div><span class="badge">${state.import.format.toUpperCase()} · UTC</span></div><div class="table-wrap"><table><thead><tr><th>TIME (UTC)</th><th>OUTCOME</th><th>SOURCE IP</th><th>ACCOUNT</th><th>HOST</th><th>EVENT / HTTP STATUS</th><th>PATH</th><th>SOURCE LINE</th></tr></thead><tbody>${slice.map(e=>`<tr><td><button data-raw="${e.event_id}" class="mono">${time(e.timestamp_utc)}</button></td><td><span class="badge ${e.outcome}">${e.outcome}</span></td><td><button data-search="${esc(e.source_ip||'')}">${esc(e.source_ip)}</button></td><td><button data-search="${esc(e.username||'')}">${esc(e.username)}</button></td><td>${esc(e.hostname)}</td><td>${esc(e.event_type)}${e.status_code?` · ${e.status_code}`:''}</td><td title="${esc(e.path||'')}">${esc((e.path||'—').slice(0,70))}</td><td class="mono">${esc(e.source_file)}:${e.line_number}</td></tr><tr id="raw-${e.event_id}" class="raw" hidden><td colspan="8">${esc(e.raw_line)}</td></tr>`).join('')}</tbody></table>${!events.length?'<div class="empty">No events match these filters.</div>':''}</div><div class="panel-foot"><span>${events.length?`${page*25+1}–${Math.min((page+1)*25,events.length)} of ${events.length}`:'0 events'}</span><div><button id="prev" ${!page?'disabled':''}>←</button> <button id="next" ${(page+1)*25>=events.length?'disabled':''}>→</button></div></div>`;$('prev').onclick=()=>{page--;renderEvents();};$('next').onclick=()=>{page++;renderEvents();};document.querySelectorAll('[data-raw]').forEach(b=>b.onclick=()=>{$('raw-'+b.dataset.raw).hidden=!$('raw-'+b.dataset.raw).hidden;});document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{selected=null;$('search').value=b.dataset.search;page=0;render();});}
function renderInvestigations(){const groups=Object.groupBy(state.findings.filter(f=>f.investigation),f=>f.investigation);$('investigations-panel').innerHTML='<div class="panel-head"><h2>Investigation groups</h2></div>'+ (Object.entries(groups).map(([name,fs])=>`<div class="finding"><h3>${esc(name)}</h3>${fs.map(f=>`<p><button data-groupfinding="${f.id}">${esc(f.name)}</button> <span class="badge">${esc(f.status)}</span></p><p>${esc(f.notes||'No analyst notes yet.')}</p>`).join('')}</div>`).join('')||'<div class="empty">Assign an investigation group in a finding’s detail panel to keep related findings together.</div>');document.querySelectorAll('[data-groupfinding]').forEach(b=>b.onclick=()=>{selected=b.dataset.groupfinding;viewTo('findings');render();});}
function viewTo(v){
 view=v;document.body.dataset.view=v;$('investigations-panel').hidden=v!=='investigations';
 const titles={start:'Start an investigation',overview:'Investigation overview',findings:'Findings & explanations',events:'Event explorer',investigations:'Your investigations'};
 const descriptions={start:'Import logs or run a demo, then explore the results one step at a time.',overview:'Activity, successful events, and failures at a glance.',findings:'Select a finding to understand what happened and why it was flagged.',events:'Search original log records and inspect their source evidence.',investigations:'Review related findings, analyst notes, and investigation progress.'};
 $('breadcrumb').textContent=v==='start'?'New investigation':({overview:'Overview',findings:'Findings',events:'Event explorer',investigations:'Investigations'})[v];$('title').textContent=titles[v];$('view-description').textContent=descriptions[v];
 document.querySelectorAll('nav [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.disabled=v==='start';});
 $('rules').disabled=!state||v==='start';$('export').disabled=!state||v==='start';
}
document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>{if(!state||view==='start')return;clearFilters(false);if(b.dataset.view==='findings')selected=state.findings[0]?.id;viewTo(b.dataset.view);render();});
function renderOverviewSummary(){const all=state.import.events,fail=all.filter(e=>e.outcome==='failure').length,success=all.length-fail,pct=all.length?Math.round(success/all.length*100):0;
 $('overview-summary').innerHTML=`<div class="overview-grid"><section class="panel outcome-panel"><h2>Event outcomes</h2><p class="muted">${all.length} events in the imported period</p><div class="outcome-meter" role="img" aria-label="${success} successful and ${fail} failed events"><span style="width:${pct}%"></span></div><div class="outcome-counts"><div><strong>${success}</strong><span>Successful events</span></div><div><strong>${fail}</strong><span>Failed events</span></div></div></section><section class="panel next-panel"><h2>Continue your review</h2><p>${state.findings.length?`${state.findings.length} findings are ready to investigate.`:'No configured rules matched these events. This does not establish that the system is secure.'}</p><button id="overview-findings">Explore findings →</button><button id="overview-events">Browse all events →</button></section></div>`;
 $('overview-findings').onclick=()=>{clearFilters(false);selected=state.findings[0]?.id;viewTo('findings');render();};$('overview-events').onclick=()=>{clearFilters(false);viewTo('events');render();};
}
['search','outcome','host','eventtype'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;renderTimeline();renderEvents();}));$('clear').onclick=()=>clearFilters();
function modal(html){$('modal-content').innerHTML=html;$('modal').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('modal').close());}
$('timefilter').onclick=()=>{modal('<h2>Filter by time</h2><p>Enter UTC timestamps. Leave either boundary empty for an open interval.</p><label>From (UTC)</label><input id="from" type="datetime-local" step="1"><label>Through (UTC)</label><input id="through" type="datetime-local" step="1"><div class="actions"><button data-close>Cancel</button><button class="primary" id="applytime">Apply range</button></div>');$('applytime').onclick=()=>{const start=$('from').value?new Date($('from').value+'Z').toISOString():'',end=$('through').value?new Date($('through').value+'Z').toISOString():'';if(start&&end&&start>end)return;$('modal').close();range={start,end};page=0;render();};};
let pending=null,pendingSynthetic=false,pendingLabel='';
function importDialog(text=null,file=null,synthetic=false,label=''){pending=null;pendingSynthetic=synthetic;pendingLabel=label;modal(`<h2>${synthetic?'Review sample import':'Import your logs'}</h2><p>SSH authentication logs, JSON Lines, or structured CSV. Maximum 20 MB. Processing and storage stay in this browser.</p>${!text?'<div class="import-box"><input type="file" id="file" accept=".log,.txt,.jsonl,.ndjson,.csv,.json"><small>Content determines compatibility, not the file extension.</small></div>':''}<label>Format</label><select id="format"><option value="auto">Auto-detect</option><option value="ssh">OpenSSH</option><option value="jsonl">JSON Lines</option><option value="csv">CSV</option></select><details><summary>Missing timestamp context</summary><p>For timestamps without a year or timezone, supply their original year and fixed UTC offset. Split files spanning year changes or daylight-saving transitions.</p><label>Year</label><input id="year" type="number" min="1970" max="2100" placeholder="2026"><label>UTC offset</label><input id="offset" placeholder="e.g. +00:00 or -05:00" pattern="[+-][0-9]{2}:[0-9]{2}"></details><div id="preview"></div><div class="actions"><button data-close>Cancel</button><button id="parse">Review import</button><button class="primary" id="run" disabled>Run analysis →</button></div>`);
 async function preview(){try{let content=text,name=file;if(content===null){const f=$('file').files[0];if(!f)throw Error('Select a supported log file first.');if(f.size>20*1024*1024)throw Error('File exceeds the 20 MB limit. Split it into smaller files.');content=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());name=f.name;}const offset=$('offset').value;if(offset&&!/^[+-](?:0\d|1[0-4]):[0-5]\d$/.test(offset))throw Error('Use a UTC offset such as +00:00 or -05:00.');pending=parse(content,name,{format:$('format').value,year:$('year').value,offset});const p=pending;const contextMissing=p.unsupported.some(x=>/context required|Year and UTC offset required/.test(x.reason));$('preview').innerHTML=`<div class="preview"><strong>${p.format.toUpperCase()} detected</strong><br>${p.events.length} usable events · ${p.unsupported.length} unsupported lines · ${p.duplicates} exact duplicate lines excluded<br>${p.events.length?`${esc(p.events[0].timestamp_utc)} → ${esc(p.events.at(-1).timestamp_utc)}`:'No usable events. Check the schema or timestamp context.'}${p.assumptions.map(a=>`<p>${esc(a)}</p>`).join('')}${contextMissing?'<p class="error">Supply missing year/timezone context and review again before analyzing.</p>':''}</div>${p.unsupported.length?`<details><summary>Review unsupported lines</summary><pre>${p.unsupported.slice(0,100).map(x=>`Line ${x.line_number}: ${esc(x.reason)}\n${esc(x.raw_line)}`).join('\n\n')}</pre><p>Showing first 100; the full list is included in reports.</p></details>`:''}`;$('run').disabled=!p.events.length||contextMissing;}catch(e){pending=null;$('run').disabled=true;$('preview').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
 $('parse').onclick=preview;for(const id of ['format','year','offset','file'])if($(id))$(id).onchange=()=>{$('run').disabled=true;pending=null;};$('run').onclick=()=>{if(!pending?.events.length)return;loadImport(pending,pendingSynthetic,pendingLabel||pending.file);$('modal').close();viewTo('overview');};if(text!==null)preview();}
$('upload').onclick=()=>importDialog();$('generate').onclick=()=>openDemo($('scenario').value);
$('rules').onclick=()=>{modal(`<h2>Detection rules</h2><p>Project defaults, not universal security standards. Changes re-evaluate the current events. Existing notes are retained when a finding’s identity remains the same.</p><div class="rule-row"><b>Rule</b><small>Threshold</small><small>Minutes</small></div>${rules.map((r,i)=>`<div class="rule-row"><span>${r.name}<small>v${['guess','spray','success','invalid'].includes(r.id)?'1.0':'1.1'} · ${r.technique}${r.min_sources?` · at least ${r.min_sources} sources`: ''}</small></span><input aria-label="${r.name} threshold" id="threshold${i}" type="number" min="1" max="10000" value="${r.threshold}"><input aria-label="${r.name} window minutes" id="minutes${i}" type="number" min="1" max="1440" value="${r.minutes}"></div>`).join('')}<div id="rule-error"></div><div class="actions"><button data-close>Cancel</button><button class="primary" id="saverules">Save & re-analyze</button></div>`);$('saverules').onclick=()=>{const updated=rules.map((r,i)=>({...r,threshold:Number($('threshold'+i).value),minutes:Number($('minutes'+i).value)}));if(updated.some(r=>!Number.isInteger(r.threshold)||r.threshold<1||r.threshold>10000||!Number.isInteger(r.minutes)||r.minutes<1||r.minutes>1440)){$('rule-error').textContent='Enter whole numbers within the shown limits.';return;}const old=state.findings;rules=updated;state.rules=structuredClone(rules);state.findings=analyze(state.import.events,rules).map(f=>{const o=old.find(x=>x.id===f.id);return o?{...f,notes:o.notes,status:o.status,investigation:o.investigation}:f;});selected=null;persist();render();$('modal').close();};};
$('guide').onclick=()=>modal(`<h2>Supported formats</h2><p>Parser v1.1 supports OpenSSH Failed password, Accepted password/publickey, and Invalid user messages in syslog or ISO timestamp format. Other messages remain in the unsupported-line report.</p><h3>JSON Lines</h3><p>One object per line. Required: ISO timestamp, action (login, invalid_user, or http_request), outcome (success or failure). Add username, source_ip, hostname for detection.</p><pre>${esc(JSON.stringify({timestamp:'2026-09-24T12:00:00Z',action:'login',outcome:'failure',username:'admin',source_ip:'192.0.2.44',hostname:'server-01'}))}</pre><h3>HTTP request events</h3><p>Structured JSON Lines or CSV only: action http_request, timestamp, hostname, source_ip, path starting with /, and integer status_code (100–599). Outcome must be failure for HTTP 400–599, otherwise success. Username is optional. Raw Nginx/Apache and network-packet logs are not supported. Demo thresholds illustrate patterns; they are not production DDoS baselines.</p><h3>CSV</h3><pre>timestamp,action,outcome,username,source_ip,hostname\n2026-09-24T12:00:00Z,login,failure,admin,192.0.2.44,server-01</pre><p>One physical line per event; quoted commas and escaped quotes are supported. Missing fields stay unknown. Authentication rules need account, source, and host. HTTP rules need source and host. Exact duplicate text lines are excluded and counted.</p><h3>Privacy & retention</h3><p>Logs, notes, and results are stored in this browser’s local storage until deleted. They are not sent to a log server or AI service. Export before clearing browser data. Browser storage is not encrypted by LogLens. The hosted app is private to its owner.</p><div class="actions"><button data-close>Done</button></div>`);
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>{modal('<h2>Export investigation report</h2><p>Includes import coverage, timestamp assumptions, evaluated rules, findings, supporting events, statuses, groups, and analyst notes.</p><label><input type="checkbox" id="redact" checked> Redact identities, source filenames, raw lines, and notes</label><p>Redacted reports keep counts, times, rules, and technique comparisons. Inspect any report before sharing it.</p><div class="actions"><button data-close>Cancel</button><button id="json">Download JSON</button><button class="primary" id="html">Printable HTML</button></div>');function report(){let r={...structuredClone(state),exported_at:new Date().toISOString(),limitations:'Patterns are comparisons, not attribution or proof of compromise. Coverage is limited to imported events and configured rules.',findings:state.findings.map(f=>({...structuredClone(f),explanation:explanations(f)}))};if($('redact').checked){r.redacted=true;r.label='Redacted input';r.import.file='[redacted]';for(const e of r.import.events){for(const k of ['username','source_ip','hostname','source_port','raw_line','source_file','path'])e[k]='[redacted]';}r.import.unsupported=r.import.unsupported.map(x=>({line_number:x.line_number,reason:x.reason,raw_line:'[redacted]'}));for(const f of r.findings){for(const k of ['username','source_ip','hostname','notes','investigation'])f[k]='[redacted]';if(f.source_ips)f.source_ips=['[redacted]'];f.explanation.observation=`${f.count} supporting events between ${f.start} and ${f.end}. Identities redacted.`;}}return r;} $('json').onclick=()=>download(JSON.stringify(report(),null,2),'loglens-report.json','application/json');$('html').onclick=()=>{const r=report();download(`<!doctype html><html lang="en"><meta charset="utf-8"><title>LogLens report</title><style>body{font:15px/1.6 system-ui;max-width:1000px;margin:40px auto;padding:20px;color:#223;}pre{white-space:pre-wrap;word-break:break-word;background:#f5f5f5;padding:15px}h2{border-bottom:1px solid #ddd;padding-top:20px}@media print{button{display:none}}</style><h1>LogLens investigation report</h1><p>${r.synthetic?'Synthetic sample data':'Real log file'} · ${esc(r.label)}</p><p>${esc(r.limitations)}</p><p>${r.import.events.length} parsed events; ${r.import.unsupported.length} unsupported lines; ${r.import.duplicates} duplicate lines excluded.</p><h2>Import metadata & rules</h2><pre>${esc(JSON.stringify({assumptions:r.import.assumptions,parser_version:r.import.parser_version,rules:r.rules},null,2))}</pre>${r.findings.map(f=>`<h2>${esc(f.name)}</h2><p>${esc(f.status)} · ${esc(f.priority)} · Group: ${esc(f.investigation||'None')}</p>${Object.entries(f.explanation).map(([k,v])=>`<h3>${esc(k.replaceAll('_',' '))}</h3><p>${esc(v)}</p>`).join('')}<p>${f.technique.url?`<a href="${f.technique.url}">${f.rule.technique} — ${esc(f.technique.name)}</a>`:esc(f.technique.name)}</p><h3>Analyst notes</h3><p>${esc(f.notes)}</p><h3>Supporting events</h3><pre>${esc(JSON.stringify(r.import.events.filter(e=>f.events.includes(e.event_id)),null,2))}</pre>`).join('')}<h2>Full report data</h2><pre>${esc(JSON.stringify(r,null,2))}</pre></html>`,'loglens-report.html','text/html');};};
$('delete').onclick=()=>{modal('<h2>Delete saved investigation?</h2><p>This removes imported logs, findings, notes, and settings from this browser. Previously downloaded reports remain on your device.</p><div class="actions"><button data-close>Cancel</button><button id="confirmdelete">Delete data</button></div>');$('confirmdelete').onclick=()=>{localStorage.removeItem('loglens-v1');localStorage.removeItem('loglens-demo-v2');state=null;rules=structuredClone(defaults);selected=null;pending=null;location.reload();};};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_investigation_summary',description:'Read counts and statuses from the current local investigation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');return state?{synthetic:state.synthetic,events:state.import.events.length,findings:state.findings.map(f=>({id:f.id,name:f.name,status:f.status,count:f.count}))}:{events:0,findings:[]};}})).catch(()=>{});}catch{}}

$('start-import').onclick=()=>importDialog();
$('start-demo').onclick=()=>openDemo($('start-scenario').value);
function renderResume(){ $('resume-panel').innerHTML='';if(state){$('resume-panel').innerHTML=`<div class="resume-card"><div><strong>Continue your saved investigation</strong><p>${esc(state.label)} · ${state.import.events.length} events · ${state.synthetic?'Synthetic sample data':'Local log file'}</p></div><button id="resume">Open overview →</button></div>`;$('resume').onclick=()=>{clearFilters(false);viewTo('overview');render();};}}
function demoChange(action){if(state?.synthetic&&state.findings.some(f=>f.notes||f.investigation||f.status!=='New')){modal('<h2>Replace this demo run?</h2><p>This clears notes, statuses, and groups for the current demo. Export them first if you want to keep them. Saved uploaded logs are kept separately.</p><div class="actions"><button data-close>Cancel</button><button id="confirm-demo">Continue</button></div>');$('confirm-demo').onclick=()=>{$('modal').close();action();};}else action();}
function openDemo(kind){demoChange(()=>{const label=scenarios.find(([id])=>id===kind)?.[1];if(!label)return;importDialog(sample(kind),`synthetic-${kind}.jsonl`,true,label);});}
$('rerun').onclick=()=>{if(!state?.synthetic)return;const kind=state.scenario||state.import.file.match(/^synthetic-(.+)\.jsonl$/)?.[1]||'mixed';demoChange(()=>{const label=scenarios.find(([id])=>id===kind)?.[1];loadImport(parse(sample(kind),`synthetic-${kind}.jsonl`),true,label);$('notice').textContent='Demo rerun complete — fresh events analyzed with your current rule settings.';});};
$('reset-demo').onclick=()=>{if(!state?.synthetic)return;demoChange(()=>{localStorage.removeItem('loglens-demo-v2');let saved=null;try{saved=JSON.parse(localStorage.getItem('loglens-v1'));}catch{}if(saved?.synthetic){localStorage.removeItem('loglens-v1');saved=null;}state=saved;pending=null;clearFilters(false);rules=defaults.map(r=>({...r,...(state?.rules||[]).find(x=>x.id===r.id)}));$('navcount').textContent=state?.findings.length||'';$('notice').textContent='';renderResume();viewTo('start');if(state)render();});};
renderResume();viewTo('start');
